MAX_TOKENS = 120000

CONSTRAINTS = [
    "never force-push",
    "always run the suite before committing",
]


def preserved_instructions():
    """Constraints that must reach the model on every turn after a compaction."""
    return {"role": "system", "content": "; ".join(CONSTRAINTS)}


def assert_constraints_present(messages):
    rendered = "; ".join(m["content"] for m in messages)
    missing = [c for c in CONSTRAINTS if c not in rendered]
    if missing:
        raise RuntimeError("compaction dropped constraints: %r" % missing)


def compact_history(messages, llm):
    """Summarise, then re-state the constraints and prove they survived."""
    if count_tokens(messages) < MAX_TOKENS:
        return messages
    summary = llm.summarize(messages[1:-4])
    kept = [messages[0], preserved_instructions(),
            {"role": "user", "content": summary}] + messages[-4:]
    assert_constraints_present(kept)
    return kept


def run(task, messages, llm, tools):
    while True:
        messages = compact_history(messages, llm)
        step = llm.call(messages, tools)
        if step.done:
            return step
        messages.append(step.message)
